// ========== 头文件包含 ==========
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
// ========== 地址定义 ==========
// unsigned int (32b)
#define S1_BASE_ADDR     0x40000000    // S1: 256MB BRAM
#define S2_BASE_ADDR     0x50000000    // S2: 0x5000_0000-0x5000_FFFF
#define S3_BASE_ADDR     0x50010000    // S3: 0x5001_0000-0x5001_FFFF
#define S4_BASE_ADDR     0x50020000    // S4: 0x5002_0000-0x5002_FFFF
#define S5_BASE_ADDR     0x50030000    // S5: 0x5003_0000-0x5003_FFFF
#define S6_BASE_ADDR     0x50040000    // S6: 0x5004_0000-0x5004_FFFF
#define S7_BASE_ADDR     0x50050000    // S7: 0x5005_0000-0x5005_FFFF
#define CTRL_BASE_ADDR   0x50060000    // CTRL
#define DMA_APB_BASE     0x00420000    // DMA APB base address
#define PLIC_BASE_ADDR   0x0C000000    // PLIC

// ========== 配置地址 ==========
// unsigned int (32b)
#define TILE_CONF_START    0x00
#define NOC_CONF_START     0x10
#define FSM_CONF_START_ID  0x1F
#define FSM_CONF_END_ID    0x20
#define GLOBAL_CONF_ID     0x42
#define RUN_PROCESS_ID     0x43
#define INTR_FRESH_ID      0x44

// ========== 位宽常量 ==========
// unsigned int (32b)
#define STRIDE_WIDTH     5
#define COUT_WIDTH       5
#define GROUP_SIZE_WIDTH 4
#define GROUP_NUM_WIDTH  4
#define K_WIDTH          5
#define WORK_MODE_WIDTH  3
#define TRUNC_BITS_WIDTH 4
#define RES_COL_IDX_WIDTH 5
#define CIN_IDX_WIDTH    6

// =========== Mac 参数 ==========
// signed int (32b)
#define ROW_SIZE        32
#define COL_SIZE        32
#define TILE_SIZE       16
#define K_PARAM          3
#define COUT_PARAM       256
#define GROUP_SIZE_PARAM 2
#define GROUP_NUM_PARAM  8
#define STRIDE_PARAM     2
#define CIN_IDX_TOTAL    8
#define RES_COL_TOTAL    1
#define RES_ROW_TOTAL    4

// ========== DMA寄存器偏移（基于dma_reg.v）==========
// unsigned int (32b)
#define DMA_CTRL         0x00          // DMA控制寄存器
#define DMA_STATUS       0x04          // DMA状态寄存器
#define DMA_ERR_CLR      0x08          // DMA错误清除寄存器
#define DESC0_MODE       0x20          // 描述符0模式配置
#define DESC0_LENGTH     0x24          // 描述符0传输长度
#define DESC0_SRC_ADDR   0x28          // 描述符0源地址
#define DESC0_DST_ADDR   0x2C          // 描述符0目标地址

// ================ PLIC寄存器偏移 ==========================
#define PLIC_PRIORITY_BASE  0x0000      // 优先级寄存器基地址
#define PLIC_PENDING_BASE   0x1000      // 挂起状态寄存器基地址
#define PLIC_ENABLE_BASE    0x2000      // 使能寄存器基地址
#define PLIC_THRESHOLD      0x200000    // 阈值寄存器
#define PLIC_CLAIM          0x200004    // 声明/完成寄存器

// ================ MAC中断源编号 ===========================
#define MAC_DONE_IRQ_ID     13          // MAC完成中断源ID（与PLIC源编号保持一致）
#define MAC_ERR_IRQ_ID      14          // MAC错误中断源ID
#define DMA_DONE_IRQ_ID     15          // DMA完成中断源ID
#define DMA_ERR_IRQ_ID      16          // DMA错误中断源ID

// ---------- 新增：上下文结构 & 辅助函数 ----------
typedef struct {
    volatile int dma_done;
    volatile int dma_err;
} dma_irq_ctx_t;

static volatile dma_irq_ctx_t *g_dma_ctx = NULL;

static inline void dma_set_context(dma_irq_ctx_t *ctx) {
    g_dma_ctx = ctx;
}

static inline dma_irq_ctx_t *dma_get_context(void) {
    return (dma_irq_ctx_t *)g_dma_ctx;
}

typedef struct {
    volatile int mac_done;
    volatile int mac_err;
} mac_irq_ctx_t;

static volatile mac_irq_ctx_t *g_mac_ctx = NULL;

static inline void mac_set_context(mac_irq_ctx_t *ctx) {
    g_mac_ctx = ctx;
}

static inline mac_irq_ctx_t *mac_get_context(void) {
    return (mac_irq_ctx_t *)g_mac_ctx;
}



