// ========= MAC 计算全局常量 =========
// ========== 内存访问函数 ==========
static inline void write_reg(unsigned int addr, unsigned int data) {
    volatile unsigned int *reg = (volatile unsigned int *)addr;
    *reg = data;
}
static inline unsigned int read_reg(unsigned int addr) {
    volatile unsigned int *reg = (volatile unsigned int *)addr;
    return *reg;
}

// ==== PLIC helpers ====
static inline void plic_set_priority(uint32_t irq_id, uint32_t priority) {
    write_reg(PLIC_BASE_ADDR + PLIC_PRIORITY_BASE + irq_id * 4u, priority);
}

static inline void plic_enable_sources(uint32_t mask) {
    uint32_t enables = read_reg(PLIC_BASE_ADDR + PLIC_ENABLE_BASE);
    write_reg(PLIC_BASE_ADDR + PLIC_ENABLE_BASE, enables | mask);
}

static inline uint32_t plic_claim_irq(void) {
    return read_reg(PLIC_BASE_ADDR + PLIC_CLAIM);
}

static inline void plic_complete_irq(uint32_t irq_id) {
    write_reg(PLIC_BASE_ADDR + PLIC_CLAIM, irq_id);
}

static inline void plic_set_threshold(uint32_t threshold) {
    write_reg(PLIC_BASE_ADDR + PLIC_THRESHOLD, threshold);
}

static inline void set_mtvec(void (*handler)(void)) {
    uintptr_t base = (uintptr_t)handler;
    __asm__ volatile("csrw mtvec, %0" :: "r"(base));
}

// ========== PLIC中断配置函数 ==========
void plic_init_mac_interrupts(void) {
    plic_set_priority(MAC_DONE_IRQ_ID, 1);
    plic_set_priority(MAC_ERR_IRQ_ID,  2);
    plic_enable_sources((1u << MAC_DONE_IRQ_ID) | (1u << MAC_ERR_IRQ_ID));
}

void plic_init_dma_interrupts(void) {
    plic_set_priority(DMA_DONE_IRQ_ID, 1);
    plic_set_priority(DMA_ERR_IRQ_ID,  3);
    plic_enable_sources((1u << DMA_DONE_IRQ_ID) | (1u << DMA_ERR_IRQ_ID));
}

// ========== PLIC中断处理函数 ==========
int plic_handle_mac_interrupt(uint32_t irq_id, mac_irq_ctx_t *ctx) {
    if (irq_id == MAC_DONE_IRQ_ID) {
        /* TODO: add MAC done handling */
        __asm__ volatile ("li x3, 710");
        write_reg(S2_BASE_ADDR + INTR_FRESH_ID * 8, 0x1);
        if (ctx) {
            ctx->mac_done = 1;
            __asm__ volatile ("li x3, 711");
        }
        plic_complete_irq(irq_id);
        __asm__ volatile ("li x3, 712");
        return 1;
    }
    if (irq_id == MAC_ERR_IRQ_ID) {
        /* TODO: add MAC error handling */
        __asm__ volatile ("li x3, 720");
        if (ctx) {
            ctx->mac_err = 1;
            __asm__ volatile ("li x3, 721");
        }
        plic_complete_irq(irq_id);
        __asm__ volatile ("li x3, 722");
        return 1;
    }
    return 0;
}
int plic_handle_dma_interrupt(uint32_t irq_id, dma_irq_ctx_t *ctx) {
    if (irq_id == DMA_DONE_IRQ_ID) {
        __asm__ volatile ("li x3, 910");
        write_reg(DMA_APB_BASE + DMA_CTRL, (8 << 8) | 0);
        if (ctx) {
            ctx->dma_done = 1;
            __asm__ volatile ("li x3, 911");
        }
        plic_complete_irq(irq_id);
        __asm__ volatile ("li x3, 912");
        return 1;
    }
    if (irq_id == DMA_ERR_IRQ_ID) {
        __asm__ volatile ("li x3, 920");
        write_reg(DMA_APB_BASE + DMA_ERR_CLR, 1);
        write_reg(DMA_APB_BASE + DMA_CTRL, (8 << 8) | 0);
        if (ctx) {
            ctx->dma_err = 1;
            __asm__ volatile ("li x3, 921");
        }
        plic_complete_irq(irq_id);
        __asm__ volatile ("li x3, 922");
        return 1;
    }
    return 0;
}
// ==== trap 入口 ====
void trap_entry(void) __attribute__((interrupt("machine")));
void trap_entry(void) {
    uint32_t mcause;
    __asm__ volatile ("csrr %0, mcause" : "=r"(mcause));

    if ((mcause & 0x80000000u) && ((mcause & 0x7Fu) == 11u)) {
        uint32_t irq_id = plic_claim_irq();
        __asm__ volatile ("mv x3, %0" :: "r"(irq_id));
        dma_irq_ctx_t *ctx = dma_get_context();
        mac_irq_ctx_t *mtx = mac_get_context();

        int handled = 0;
        handled |= plic_handle_dma_interrupt(irq_id, ctx);
        handled |= plic_handle_mac_interrupt(irq_id, mtx);

        if (!handled && irq_id) {
            plic_complete_irq(irq_id);
        }
    }
}

// ========== 启用PLIC外部中断 ==========
void enable_plic_interrupts(void) {
   // 在mie寄存器中启用外部中断
   __asm__ volatile ("li t0, 0x800\n\t"
    "csrs mie, t0");

    // 在mstatus寄存器中启用全局中断
    __asm__ volatile ("csrs mstatus, 0x8");
}

// ========== 延时函数 ==========
void delay_cycles(int cycles) {
    for(int i = 0; i < cycles; i++) {
        __asm__ volatile ("nop");
    }
}

void short_delay(void) {delay_cycles(100); }
void long_delay(void)  {delay_cycles(1000);}

// ========== 配置Tiles和NoC ==========
void config_tiles_and_noc(int groupSize, int k) {

    // 配置Tile
    __asm__ volatile ("li x3, 20");
    for(int tileId = 0; tileId < TILE_SIZE; tileId++) {
        int featureMapLine = tileId / groupSize;
        int writeId = (groupSize - 1) - (tileId % groupSize);
        int workMode2 = 0;

        uint32_t configData = ((featureMapLine & 0xFF) << 16) |
                                ((workMode2 & 0x7) << 13) |
                                ((writeId & 0xFF) << 5) |
                                ((k - 1) & 0x1F);

        // 写入 S1
        write_reg(S2_BASE_ADDR + (TILE_CONF_START + tileId) * 8, configData);
        short_delay();
    }

    // 配置NOC
    __asm__ volatile ("li x3, 21");
    for(int nocId = 0; nocId < TILE_SIZE - 1; nocId++) {  // TILE_SIZE-1 = 15
        int upperGroup = nocId / groupSize;
        int lowerGroup = (nocId + 1) / groupSize;
        int systolic = (upperGroup != lowerGroup);
        int add = (upperGroup == lowerGroup);
        int deliver = 1;

        uint32_t configData = ((deliver & 0x1) << 3) | ((systolic & 0x1) << 2) | ((add & 0x1) << 1) | (0 & 0x1);
        // 写入 S1
        write_reg(S2_BASE_ADDR + (NOC_CONF_START + nocId) * 8, configData);
        short_delay();
    }
}

// ========== SRAM控制 ==========
void set_sram_control(unsigned int weight_sram0_ctrl,
    unsigned int weight_sram1_ctrl,
    unsigned int output_sram0_ctrl,
    unsigned int output_sram1_ctrl) {
    uint32_t sram_ctrl_data = ((output_sram1_ctrl & 0x1) << 3) | ((output_sram0_ctrl & 0x1) << 2) |
                              ((weight_sram1_ctrl & 0x1) << 1) | ((weight_sram0_ctrl & 0x1) << 0);
    __asm__ volatile ("li x3, 10");
    write_reg(CTRL_BASE_ADDR, sram_ctrl_data);
    long_delay();
}

// ========== 等待DMA完成（轮询方式）==========
int wait_dma_complete(void) {
    dma_irq_ctx_t *ctx = dma_get_context();
    // if (!ctx) {
    //     return -2;
    // }

    int timeout = 100000;
    __asm__ volatile ("li x3, 400");
    while (timeout-- > 0) {
        __asm__ volatile ("li x3, 410");
        if (ctx->dma_err) {
            __asm__ volatile ("li x3, 411");
            ctx->dma_err = 0;
            write_reg(DMA_APB_BASE + DMA_ERR_CLR, 1);
            write_reg(DMA_APB_BASE + DMA_CTRL, (8 << 8) | 0);
            __asm__ volatile ("li x3, 401");
            return -1;
        }
        if (ctx->dma_done) {
            __asm__ volatile ("li x3, 412");
            ctx->dma_done = 0;
            write_reg(DMA_APB_BASE + DMA_CTRL, (8 << 8) | 0);
            __asm__ volatile ("li x3, 402");
            return 0;
        }
        __asm__ volatile ("li x3, 413");
        __asm__ volatile ("wfi");
        __asm__ volatile ("li x3, 414");
    }

    __asm__ volatile ("li x3, 404");
    return -2;
}

// ========== DMA 传输函数 ==========
/*
 * 执行DMA传输：配置描述符 → 启动传输 → 等待完成
 * 参数：
 *   src_addr: 源地址
 *   dst_addr: 目标地址
 *   length: 传输字节数
 * 返回值：
 *   0: 成功
 *   -1: DMA错误
 *   -2: 超时
 */
void dma_transfer(unsigned int src_addr, unsigned int dst_addr, unsigned int length) {
    // 1. 配置描述符0：增量模式，使能
    write_reg(DMA_APB_BASE + DESC0_MODE, 1);
    short_delay();

    // 2. 配置传输长度
    write_reg(DMA_APB_BASE + DESC0_LENGTH, length);
    short_delay();

    // 3. 配置源地址
    write_reg(DMA_APB_BASE + DESC0_SRC_ADDR, src_addr);
    short_delay();

    // 4. 配置目标地址
    write_reg(DMA_APB_BASE + DESC0_DST_ADDR, dst_addr);
    short_delay();

    // 5. 验证配置（可选，用于调试）
    unsigned int verify_mode   = read_reg(DMA_APB_BASE + DESC0_MODE);
    unsigned int verify_length = read_reg(DMA_APB_BASE + DESC0_LENGTH);
    unsigned int verify_src    = read_reg(DMA_APB_BASE + DESC0_SRC_ADDR);
    unsigned int verify_dst    = read_reg(DMA_APB_BASE + DESC0_DST_ADDR);

    // 6. 检查配置后的状态
    unsigned int config_status = read_reg(DMA_APB_BASE + DMA_STATUS);
    if ((config_status >> 1) & 0x01) {  // 检查错误位
        __asm__ volatile ("li x3, 90");
    }

    // 7. 启动DMA传输 (maxburst=8, start=1)
    write_reg(DMA_APB_BASE + DMA_CTRL, (8 << 8) | 1);
    // long_delay();  // 给DMA一些时间开始工作
    __asm__ volatile ("li x3, 900");
    // 8. 等待传输完成
    int dma_result = wait_dma_complete();
    __asm__ volatile ("li x3, 901");
    if (dma_result != 0) {
        // DMA传输失败
        if (dma_result == -1) {
            __asm__ volatile ("li x3, 91");  // DMA错误
        } else {
            __asm__ volatile ("li x3, 92");  // DMA超时
        }
    }

}

// ========= 权重写入函数 =============
void drive_weights_from_files(int length){
    __asm__ volatile ("li x3, 30");

    for(int i = 0; i < 144; i++) {
        for(int j = 7; j >= 0; j--){
            // 写入 S1
            write_reg(S1_BASE_ADDR + i*32 + (7-j)*4, weight_data[i][j]);
            short_delay();
        }
    }

    long_delay();

    __asm__ volatile ("li x3, 31");

    // 权重将会送至Mac的0X20000 RAM中，AXI总线64bit，相邻地址+8，权重长度为length，每个是256b，32 byte
    dma_transfer(S1_BASE_ADDR, S4_BASE_ADDR, length * 32);
    long_delay();
}

// ========= 特征写入sram函数 =============
void drive_features_to_sram(void){
    __asm__ volatile ("li x3, 41");

    for(int i = 0; i < 2048; i++) {
        for(int j = 15; j >= 0; j--){
            // 写入 S1
            write_reg(S1_BASE_ADDR + i*64 + (15-j)*4, feature_data[i][j]);
            short_delay();
        }
    }

    long_delay();
}

// ========== 特征数据写入 ==========
void drive_feature_from_files(int cinIdx, int resolutionColIdx, int resolutionRowIdx,
    int groupSize, int groupNum, int resolutionRowIdxTotal) {
    __asm__ volatile ("li x3, 70");

    for(int tileId = 0; tileId < TILE_SIZE; tileId++) {
        int startRowCin = (cinIdx * (ROW_SIZE * groupSize) +
                          ((groupSize - 1 - (tileId % groupSize)) * ROW_SIZE)) *
                         (groupNum * resolutionRowIdxTotal);  // RES_ROW_TOTAL = 2

        int startRowHeight = (resolutionRowIdx * groupNum) + (tileId / groupSize);
        int startRow = startRowCin + startRowHeight;

        __asm__ volatile ("mv x3, %0" : : "r"(tileId) : "x3");
        for(int r = 0; r < ROW_SIZE; r++) {
            int addr_in_hex = (startRow + r * groupNum * resolutionRowIdxTotal) * 8;  // RES_ROW_TOTAL = 2
            int start_segment;
            if (resolutionColIdx == 0) {
                start_segment = 0;
            }
            else {
                start_segment = 4;
            }
            // DMA 搬运
            dma_transfer(S1_BASE_ADDR + addr_in_hex + start_segment * 8, S3_BASE_ADDR | (((tileId & 0xFF) << 5 | (r & 0x1F)) << 5), 4 * 8);
            long_delay();
        }
    }
}

int wait_mac_complete(void) {
    mac_irq_ctx_t *ctx = mac_get_context();
    // if (!ctx) {
    //     return -2;
    // }

    int timeout = 100000;
    __asm__ volatile ("li x3, 1000");
    while (timeout-- > 0) {
        __asm__ volatile ("li x3, 1010");
        if (ctx->mac_err) {
            __asm__ volatile ("li x3, 1011");
            ctx->mac_err = 0;
            __asm__ volatile ("li x3, 1012");
            return -1;
        }
        if (ctx->mac_done) {
            __asm__ volatile ("li x3, 1013");
            ctx->mac_done = 0;
            write_reg(S2_BASE_ADDR + INTR_FRESH_ID * 8, 0x1);
            __asm__ volatile ("li x3, 1014");
            return 0;
        }
        __asm__ volatile ("li x3, 1015");
        __asm__ volatile ("wfi");
        __asm__ volatile ("li x3, 1016");
    }

    __asm__ volatile ("li x3, 1017");
    return -2;
}

// ========== 运行推理过程 ==========
void run_process(int cinIdx, int resolutionColIdx, int resolutionRowIdx, int k, int cout,
    int groupSize, int groupNum, int stride, int cinIdxTotal, int resolutionColIdxTotal,
    int resolutionRowIdxTotal, int dataFlowMode, int truncateBits, int truncateEn, unsigned int featurePingpongFlag,
    unsigned int weightPingpongFlag, unsigned int outputPingpongFlag, unsigned int pingpongEnFlag, int planeWorkMode) {
    __asm__ volatile ("li x3, 52");

    // 切换到MAC控制
    set_sram_control(1, 1, 1, 1);  // 所有SRAM切换到MAC控制

    // 配置FSM参数
    int isFinalCinIdx, bnEn, actEn, poolEn, actionMode;
    isFinalCinIdx = (cinIdx == (cinIdxTotal - 1)); bnEn = 0; actEn = 0; poolEn = 0;
    actionMode = ((dataFlowMode & 0x1) << 0) | ((isFinalCinIdx & 0x1) << 1) | ((bnEn & 0x1) << 2) | ((actEn & 0x1) << 3) | ((poolEn & 0x1) << 4);

    __asm__ volatile ("li x3, 53");
    // 使用位宽常量进行计算（匹配Verilog）
    unsigned int stride_w = (stride-1) % (1 << STRIDE_WIDTH);
    unsigned int cout_m1_w = (cout-1) % (1 << COUT_WIDTH);
    unsigned int groupNum_m1_w = (groupNum-1) % (1 << GROUP_NUM_WIDTH);
    unsigned int groupSize_m1_w = (groupSize-1) % (1 << GROUP_SIZE_WIDTH);
    unsigned int k_m1_w = (k-1) % (1 << K_WIDTH);

    // 计算normalConfig（匹配Verilog位拼接）
    unsigned int normalConfig = ((stride_w & 0x1F) << (COUT_WIDTH + GROUP_NUM_WIDTH + GROUP_SIZE_WIDTH + K_WIDTH)) |
                               ((cout_m1_w & 0x1F) << (GROUP_NUM_WIDTH + GROUP_SIZE_WIDTH + K_WIDTH)) |
                               ((groupNum_m1_w & 0xF) << (GROUP_SIZE_WIDTH + K_WIDTH)) |
                               ((groupSize_m1_w & 0xF) << K_WIDTH) |
                               (k_m1_w & 0x1F);

    // 直接写入Mac
    write_reg(S2_BASE_ADDR + FSM_CONF_START_ID * 8, normalConfig);

    __asm__ volatile ("li x3, 54");
    // 配置特殊参数
    unsigned int trunc_w = truncateBits % (1 << TRUNC_BITS_WIDTH);
    unsigned int pwm_w   = planeWorkMode % (1 << WORK_MODE_WIDTH);
    unsigned int rci_w = resolutionColIdx % (1 << RES_COL_IDX_WIDTH);
    unsigned int cix_w = cinIdx % (1 << CIN_IDX_WIDTH);

    unsigned int specialConfig = ((truncateEn ? 1 : 0) << (TRUNC_BITS_WIDTH + WORK_MODE_WIDTH + RES_COL_IDX_WIDTH + CIN_IDX_WIDTH)) |
                                ((trunc_w & 0xF) << (WORK_MODE_WIDTH + RES_COL_IDX_WIDTH + CIN_IDX_WIDTH)) |
                                ((pwm_w & 0x7) << (RES_COL_IDX_WIDTH + CIN_IDX_WIDTH)) |
                                ((rci_w & 0x1F) << CIN_IDX_WIDTH) |
                                (cix_w & 0x3F);

    // 直接写入Mac
    write_reg(S2_BASE_ADDR + FSM_CONF_END_ID * 8, specialConfig);

    // 加载特征数据
    __asm__ volatile ("li x3, 55");
    drive_feature_from_files(cinIdx, resolutionColIdx, resolutionRowIdx, groupSize, groupNum, resolutionRowIdxTotal);

    __asm__ volatile ("li x3, 56");

    featurePingpongFlag = !featurePingpongFlag;
    if(pingpongEnFlag){
        weightPingpongFlag = !weightPingpongFlag;
        outputPingpongFlag = !outputPingpongFlag;
    }

    unsigned int action5 = actionMode % 32;
    // 配置全局参数
    uint32_t globalConf = ((featurePingpongFlag & 0x1F) << 31) |
                             ((weightPingpongFlag & 0x1F) << 30) |
                             ((outputPingpongFlag & 0x1F) << 29) |
                             ((action5 & 0x1F) << 0);
    write_reg(S2_BASE_ADDR + GLOBAL_CONF_ID * 8, globalConf);

    __asm__ volatile ("li x3, 57");
    // 触发运行
    write_reg(S2_BASE_ADDR + RUN_PROCESS_ID * 8, 0x1);

    // 等待完成
    int mac_result = wait_mac_complete();
    __asm__ volatile ("li x3, 58");
    if (mac_result != 0) {
        // DMA传输失败
        if (mac_result == -1) {
            __asm__ volatile ("li x3, 588");  // mac错误
        } else {
            __asm__ volatile ("li x3, 589");  // mac超时
        }
    }
    long_delay();
}

// ========== 输出结果读取并DMA搬运到S1 ==========
void print_output_results(int resolutionColIdx, int resolutionRowIdx, int outputPingpongFlag) {
    __asm__ volatile ("li x3, 80");  // 开始输出结果处理

    // 切换SRAM控制：输出SRAM切换到外部控制（AXI），以便读取结果
    set_sram_control(1, 1, 0, 0); // weight_sram0, weight_sram1 = 1 (MAC), output_sram0, output_sram1 = 0 (AXI)
    long_delay();

    // 计算参数
    int cout = COUT_PARAM;  // 输出通道数
    int groupNum = GROUP_NUM_PARAM;  // 组数
    int rows_per_channel = groupNum;  // 每个通道的行数
    int addresses_per_channel = rows_per_channel;  // 每个通道的地址数

    // 计算S1中的目标地址偏移
    // 为每个分辨率组合预留空间：cout * groupNum * 32字节
    int s1_offset = (resolutionRowIdx * RES_COL_TOTAL + resolutionColIdx) * cout * groupNum * 32;
    unsigned int s1_base_addr = S1_BASE_ADDR + s1_offset;

    // 选择源SRAM地址
    unsigned int src_base_addr;
    if (outputPingpongFlag == 0) {
        src_base_addr = S3_BASE_ADDR;  // ping SRAM
        __asm__ volatile ("li x3, 81");  // 使用ping SRAM
    } else {
        src_base_addr = S4_BASE_ADDR;  // pong SRAM
        __asm__ volatile ("li x3, 82");  // 使用pong SRAM
    }

    __asm__ volatile ("li x3, 83");  // 开始数据搬运

    // 对于每个输出通道
    for (int ch = 0; ch < cout; ch++) {
        int start_addr_offset = ch * addresses_per_channel * 32;  // 每行32字节

        // DMA搬运整个通道的数据
        unsigned int src_addr = src_base_addr + start_addr_offset;
        unsigned int dst_addr = s1_base_addr + ch * rows_per_channel * 32;
        unsigned int length = rows_per_channel * 32;  // 每个通道的总字节数

        dma_transfer(src_addr, dst_addr, length);
        long_delay();

        __asm__ volatile ("li x3, 84");  // 通道搬运完成
    }

    // 恢复SRAM控制（可选，切换回MAC控制）
    // set_sram_control(1, 1, 1, 1);

    __asm__ volatile ("li x3, 85");  // 输出结果处理完成
}

// ========== 主测试流程 ==========
int main(void) {

    int planeWorkMode;
    int k, cout, groupSize, groupNum, stride;
    int cinIdxTotal, resolutionColIdxTotal, resolutionRowIdxTotal;

    int dataFlowMode, truncateBits, truncateEn;
    unsigned int featurePingpongFlag, weightPingpongFlag, outputPingpongFlag, pingpongEnFlag;
    k = K_PARAM; cout = COUT_PARAM; groupSize = GROUP_SIZE_PARAM; groupNum = GROUP_NUM_PARAM; stride = STRIDE_PARAM;
    cinIdxTotal = CIN_IDX_TOTAL; resolutionColIdxTotal = RES_COL_TOTAL; resolutionRowIdxTotal = RES_ROW_TOTAL;
    featurePingpongFlag = 0; weightPingpongFlag = 0; outputPingpongFlag = 0; pingpongEnFlag = 0;
    planeWorkMode = 0; dataFlowMode = 0; truncateBits = 0; truncateEn = 0;
    
    dma_irq_ctx_t dma_ctx = {0};
    mac_irq_ctx_t mac_ctx = {0};
    dma_set_context(&dma_ctx);
    mac_set_context(&mac_ctx);
    // 初始化PLIC MAC中断
    plic_set_threshold(0);
    plic_init_mac_interrupts();
    plic_init_dma_interrupts();

    // 启用中断
    set_mtvec(trap_entry);
    enable_plic_interrupts();

    // long_delay();

    // === 步骤1: 初始化等待（在tb_top.v中已经处理）===
    // 初始化SRAM控制：所有SRAM切换到外部控制，直接写入（不通过DMA传输）
    __asm__ volatile ("li x3, 1");
    set_sram_control(0, 0, 0, 0);

    // === 步骤2: 配置Tiles和NoC ===
    // 直接写入 S2，地址加8
    __asm__ volatile ("li x3, 2");
    config_tiles_and_noc(groupSize, k);

    // === 步骤3：写入权重 ===
    __asm__ volatile ("li x3, 3");
    int length = cout*cinIdxTotal*groupSize;
    drive_weights_from_files(length);

    // // === 步骤4: 写入特征数据至sram ===
     __asm__ volatile ("li x3, 4");
     drive_features_to_sram();

    // // === 步骤5: 主推理循环 ===
    __asm__ volatile ("li x3, 5");
    for(int resolutionRowIdx = 0; resolutionRowIdx < RES_ROW_TOTAL; resolutionRowIdx++) {
        for(int resolutionColIdx = 0; resolutionColIdx < RES_COL_TOTAL; resolutionColIdx++) {
            // 设置planeWorkMode
            if (resolutionRowIdx == 0) {
                planeWorkMode = (resolutionColIdx == 0) ? 0 : 4;
            } else {
                planeWorkMode = (resolutionColIdx == 0) ? 1 : 2;
            }
            __asm__ volatile ("li x3, 6");
            // 运行第一个cinIdx
            run_process(0, resolutionColIdx, resolutionRowIdx, k, cout, groupSize, groupNum, stride,cinIdxTotal,
               resolutionColIdxTotal, resolutionRowIdxTotal, dataFlowMode, truncateBits, truncateEn, featurePingpongFlag,
               weightPingpongFlag, outputPingpongFlag, pingpongEnFlag, planeWorkMode);

            // 设置planeWorkMode为3
            planeWorkMode = 3;

            __asm__ volatile ("li x3, 7");
            // 运行剩余的cinIdx
            for(int cinIdx = 1; cinIdx < CIN_IDX_TOTAL; cinIdx++) {
                run_process(cinIdx, resolutionColIdx, resolutionRowIdx, k, cout, groupSize, groupNum, stride,cinIdxTotal,
                        resolutionColIdxTotal, resolutionRowIdxTotal, dataFlowMode, truncateBits, truncateEn, featurePingpongFlag,
                        weightPingpongFlag, outputPingpongFlag, pingpongEnFlag, planeWorkMode);
            }

            __asm__ volatile ("li x3, 8");
            // 输出结果
            print_output_results(resolutionColIdx, resolutionRowIdx, outputPingpongFlag);
            
        }
    }

    __asm__ volatile ("li x3, 509");

}
